existing={s["id"]:s for s in sources_payload["sources"]}; urlmap={str(s.get("url") or ""):s["id"] for s in sources_payload["sources"] if s.get("url")}
def ensure(r):
    sid=r["id"]; url=str(r.get("url") or "")
    if sid in existing: t=existing[sid]
    elif url and url in urlmap: sid=urlmap[url]; t=existing[sid]
    else:
        t=dict(r); t["used_by_unit_ids"]=[]; sources_payload["sources"].append(t); existing[sid]=t
        if url: urlmap[url]=sid
    for k,v in r.items():
        if v not in (None,"",[]) and (not t.get(k) or k in {"verification_status","locator","limitations","curricular_function"}): t[k]=v
    if "BIOINST-U04" not in t.setdefault("used_by_unit_ids",[]): t["used_by_unit_ids"].append("BIOINST-U04")
    return sid
